// Crisp ký "[timestamp;raw_body]" bằng HMAC-SHA256. Node này ghép chuỗi cần ký; node Crypto kế tiếp tính HMAC
// (n8n chặn module crypto trong Code node). Thiếu header hoặc timestamp lệch quá 5 phút thì bỏ.
const MAX_SKEW_S = 300;
const h = $input.first().json.headers || {};
const ts = String(h['x-crisp-request-timestamp'] || '');
const signature = String(h['x-crisp-signature'] || '');
if (!/^\d+$/.test(ts) || !/^[0-9a-f]{64}$/.test(signature)) return [];
const tsSeconds = ts.length > 11 ? Number(ts) / 1000 : Number(ts);
if (Math.abs(Date.now() / 1000 - tsSeconds) > MAX_SKEW_S) return [];
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
return [{ json: { signed: '[' + ts + ';' + raw + ']', signature, raw } }];

// So chữ ký Crisp với HMAC do node "Sign Body" tính. Secret còn là placeholder thì từ chối mọi request.
const secret = String($('Sign Body').params.secret || '');
if (secret.startsWith('REPLACE_') || secret.length < 16) throw new Error('Crisp hook secret chưa được cấu hình');
const ALLOWED = ['message:send', 'message:received', 'session:set_segments', 'session:set_state', 'session:set_email'];
const { expected, signature, raw } = $input.first().json;
if (typeof expected !== 'string' || expected.length !== signature.length) return [];
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ signature.charCodeAt(i);
if (diff !== 0) return [];
const b = JSON.parse(raw);
if (!ALLOWED.includes(b.event) || !b.website_id || !b.data) return [];
return [{ json: { p_event: { website_id: b.website_id, event: b.event, data: b.data } } }];
